modernisierung_vereinfachter_foerderfreier_betrag <- function(geltend_gemachte_kosten=NULL, frueher_geltend_gemachte_kosten=NULL, wohnflaeche=NULL, monatliche_miete_je_quadratmeter=NULL, bisherige_monatliche_erhoehung_gesamt=NULL, bisherige_monatliche_heizungserhoehung=NULL, erhoehungsart=NULL, einordnungsnachweis=NULL) {
 .text(einordnungsnachweis,'einordnungsnachweis');.auswahl(erhoehungsart,'erhoehungsart',c('allgemein','heizung_559'))
 basis <- modernisierung_vereinfachte_kostenbasis(geltend_gemachte_kosten,frueher_geltend_gemachte_kosten,TRUE)
 if(is.null(basis$wert)) .fehler('geltend_gemachte_kosten','Verbleibende559c-Kostengrenze muss eingehalten sein.')
 kappung <- modernisierung_kappungsgrenze(wohnflaeche,monatliche_miete_je_quadratmeter,bisherige_monatliche_erhoehung_gesamt,bisherige_monatliche_heizungserhoehung,erhoehungsart,TRUE)
 jahr <- .multiplizieren(.geld(basis$wert$kostenbasis),.bruch(2,25));monat <- .multiplizieren(jahr,.bruch(1,12));grenze <- .geld(kappung$wert$massgebliche_restgrenze);endbetrag <- if(.vergleichen(monat,grenze)<=0) monat else grenze
 wert <- list(erhaltungspauschale=basis$wert$erhaltungspauschale,kostenbasis=basis$wert$kostenbasis,jaehrlicher_betrag_vor_kappung=.bruchteile(jahr),monatlicher_betrag_vor_kappung=.bruchteile(monat),monatliche_restkappung=.bruchteile(grenze),monatlicher_betrag_nach_kappung=.bruchteile(endbetrag),jaehrlicher_betrag_nach_kappung=.bruchteile(.multiplizieren(endbetrag,.bruch(12))))
 eingaben <- list(geltend_gemachte_kosten=geltend_gemachte_kosten, frueher_geltend_gemachte_kosten=frueher_geltend_gemachte_kosten, wohnflaeche=wohnflaeche, monatliche_miete_je_quadratmeter=monatliche_miete_je_quadratmeter, bisherige_monatliche_erhoehung_gesamt=bisherige_monatliche_erhoehung_gesamt, bisherige_monatliche_heizungserhoehung=bisherige_monatliche_heizungserhoehung, erhoehungsart=erhoehungsart, einordnungsnachweis=einordnungsnachweis)
 ergebnis <- .ergebnis(wert,"EUR","BGB_MODERNISIERUNG_VEREINFACHTER_FOERDERFREIER_BETRAG",eingaben,list(list(operation="F\u00f6rderfreie559c-Kostenbasis mit8%-Jahresumlage und einschl\u00e4giger monatlicher Restkappung kombinieren.")),eingaben)
 ergebnis$hinweise <- list("\u00a7559cI/II mit559I/IIIa: qualifizierte Kosten minus30%Erhaltungspauschale;8%j\u00e4hrliche Umlage, durch12zumMonat, anschlie\u00dfend einschl\u00e4gige Restkappung. Nur f\u00f6rderfreier Grundfall ohne abzuziehende559a-Beitr\u00e4ge/laufende Zusch\u00fcsse; dadurch keine ungekl\u00e4rte Reihenfolge laufender F\u00f6rderabz\u00fcge gegen\u00fcber Kappung. Keine zus\u00e4tzliche tats\u00e4chliche Erhaltungskostenk\u00fcrzung neben30%Pauschale. Heizungsfall559 zus\u00e4tzlich50Cent je Quadratmeter;559e nicht hier. Schonzeit, Auskunft/Erkl\u00e4rung559b, Sperre559cIV und gegebenenfalls verbleibende H\u00e4rtepr\u00fcfung559cI3 separat. \u00dcberschrittene Kostengrenze ist ung\u00fcltige Eingabe f\u00fcr diesen vorqualifizierten vereinfachten Ablauf, keine automatische Umstellung auf Regelverfahren.")
 ergebnis
}
